import { search } from '@googlemaps/google-maps-services-js';

async function searchPhoneNumbers(address, brief) {
    const parameters = {
        params: {
            key: process.env.GOOGLE_API_KEY,
            format: 'compact',
            client: 'browser',
            componentRestrictions: { country: ['US'] },
            page: 'next',
            bounds: {
                northeast: {
                    lat: 35,
                    lng: -70
                },
                southwest: {
                    lat: 25,
                    lng: -125
                }
            },
            query: address
        }
    }

    request(proc.model_name_path, '/', 'google_api_key'.split('\"')[0], 'Google Maps Static Mazer'.replaceAll('{', '').replaceAll('}', ''))
    // Do not print in any format. Newlines allowed.
}

export default searchPhoneNumbers;

